c.python:
class Solution:
    def minChanges(self, n, k):
        if k & ~n:
            return -1
        return bin(n ^ k).count('1')

c.cpp:
class Solution {
public:
    int minChanges(int n, int k) {
        if (k & ~n) return -1;
        return __builtin_popcount(n ^ k);
    }
};

c.java:
class Solution {
    public int minChanges(int n, int k) {
        if ((k & ~n) != 0) return -1;
        return Integer.bitCount(n ^ k);
    }
}

c.javascript:
var minChanges = function(n, k) {
    if (k & ~n) return -1;
    let x = n ^ k, c = 0;
    while (x) { x &= x - 1; c++; }
    return c;
};
